export function update(ray, world) {
  if (!ray.cx && !ray.cy) {
    // Pick a centre once, offset from the ray's start so the circle is wide.
    ray.cx = ray.x + (Math.random() < 0.5 ? -180 : 180);
    ray.cy = ray.y + (Math.random() < 0.5 ? -120 : 120);
